// Auto-generated default SK Mutasi docx template base64
export const DEFAULT_SK_MUTASI_DOCX_B64 = "";

export function getDefaultSKMutasiArrayBuffer(): ArrayBuffer {
  const binaryString = atob(DEFAULT_SK_MUTASI_DOCX_B64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes.buffer;
}
